window.STORY_CHAPTERS["cdf9eac00ee4f681e"]={"id":"cdf9eac00ee4f681e","lines":[{"uid":"talk.event_ch13_03#originalText","id":"talk.event_ch13_03","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"爱丽丝大人……请回到骑士团吧！","en":"Please...Alice... Come back to the Integrity Knights!","ja":"アリス様……騎士団にお戻りください!"},"kind":"dialogue"},{"uid":"talk.event_ch13_04#originalText","id":"talk.event_ch13_04","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今后一定也会因为各种事而迷惑、烦恼以及受到挫折……但我还是会往前进。","en":"There are going to be a lot of instances where we're lost, worried,  and discouraged... but we need to move forward.","ja":"これからも色々迷ったり、悩んだり挫けたりするでしょうけど……でも、前に進むわ"},"kind":"dialogue"},{"uid":"talk.event_ch13_05#originalText","id":"talk.event_ch13_05","speaker":{"cn":"明日奈","en":"Asuna","ja":"明日奈"},"text":{"cn":"我想在那里对桐人说「你真的很努力了」。","en":"I want to tell Kirito. That he did everything he could.","ja":"向こうで、キリト君に言ってあげたい頑張ったね、って"},"kind":"dialogue"},{"uid":"talk.event_ch13_06#originalText","id":"talk.event_ch13_06","speaker":{"cn":"加百列","en":"Gabriel","ja":"ガブリエル"},"text":{"cn":"………………","en":"...","ja":"………………"},"kind":"dialogue"},{"uid":"talk.event_55_01#originalText","id":"talk.event_55_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人和有纪他们两个又在单独聊天吗？总觉得，心情有点复杂。","en":"Are Kirito and Yuuki talking again? I don't know how to feel about this...","ja":"キリトくんとユウキまたふたりで話してるの?なんか、複雑な気分だなあ"},"kind":"dialogue"},{"uid":"talk.event_55_02#originalText","id":"talk.event_55_02","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"桐人和亚丝娜真的很登对。但是，我也跟亚丝娜……","en":"Kirito and Asuna really do compliment each other. On the other hand, me and Asuna...","ja":"キリトとアスナは本当にお似合いだよねでも、ボクだってアスナと……"},"kind":"dialogue"},{"uid":"talk.event_55_03#originalText","id":"talk.event_55_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"居然能够和绝剑的有纪再次认真比剑，真的要感谢统一决斗大会。","en":"I'll have to thank the tournament for giving me another chance to cross swords with Yuuki's Absolute Sword.","ja":"絶剣のユウキともう一度本気で剣を交えることができるなんてトーナメントに感謝しないとな"},"kind":"dialogue"},{"uid":"talk.event_55_04#originalText","id":"talk.event_55_04","speaker":{"cn":"有纪","en":"Yuuki","ja":"ユウキ"},"text":{"cn":"要是我能在统一决斗大会胜出，我……有些话想跟亚丝娜说！","en":"If I win the Unity Duel Tournament, There's...There's something I want to tell Asuna!","ja":"統一デュエルトーナメントに勝ったらボク……アスナに伝えたいことがあるんだ!"},"kind":"dialogue"},{"uid":"talk.event_55_05#originalText","id":"talk.event_55_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人和有纪对战的话，我应该支持哪边……不对，我两边都支持！","en":"If Kirito and Yuuki win, who should I support...? I'll support both of them!","ja":"キリトくんとユウキが戦ったらどっちを応援すれば……ううん、どっちも応援するわ!"},"kind":"dialogue"},{"uid":"talk.event_53_01#originalText","id":"talk.event_53_01","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"最高司祭虽然任性自尊心又高，但是作为喝酒的伴也算不错。","en":"Her Eminence may be erratic and prideful by nature, but she's not too bad of a drinking companion.","ja":"猊下は気まぐれで気位が高いが一緒に酒を飲む相手としてはなかなか悪くねぇ"},"kind":"dialogue"},{"uid":"talk.event_53_02#originalText","id":"talk.event_53_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"集成骑士和最高司祭的天命也被冻结了，所以应该不用担心寿命才对……","en":"The lifespan of an Integrity Knight as well as Her Eminence are sealed. So we mustn't be afraid of our mortality...","ja":"整合騎士も最高司祭猊下も、天命が凍結されている。だから寿命に怯えることはないはずなんだが……"},"kind":"dialogue"},{"uid":"talk.event_53_03#originalText","id":"talk.event_53_03","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"天界……那边的世界根本和我们一样……不，那里住着更多下等的人类。","en":"Heaven...Is a place where other people like us... No, it's a place where sub-humans reside.","ja":"天界……向こうの世界なんて、私たちと同じ……いえ、もっと下衆な人間たちが住んでいるのよ"},"kind":"dialogue"},{"uid":"talk.event_53_04#originalText","id":"talk.event_53_04","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"那个贝尔库利的话，说不定能够明白。明白我所担忧的事的一小部份……","en":"Could it be that Bercouli understands? The difficult situation I am in. Or at least a part of it...","ja":"あのベルクーリなら、もしかしたらわかるかしら。私が抱えている苦悩のほんの一部くらいなら……"},"kind":"dialogue"},{"uid":"talk.event_54_01#originalText","id":"talk.event_54_01","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"就算是在《ALO》我也没有打算改变我的战斗风格。即使不能用枪，也能用弓。","en":"Even on ALO, I don't plan on changing my play style. Even if there are no guns, I'll fight with a bow.","ja":"《ALO》でもプレイスタイルを変えるつもりはないわ銃はなくても、弓で戦う"},"kind":"dialogue"},{"uid":"talk.event_54_02#originalText","id":"talk.event_54_02","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"猫妖的视力很好。对狙击手来说，视力是很重要的能力值喔。","en":"Cait Siths have great vision. For snipers, vision is an important parameter.","ja":"ケットシーは視力がいいのねスナイパーにとって視力は大事なパラメータよ"},"kind":"dialogue"},{"uid":"talk.event_54_03#originalText","id":"talk.event_54_03","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"我胸前的坠饰……曾经保护过我和桐人的性命。","en":"The pendant on my chest... Protected not only my life, but Kirito's as well.","ja":"私の胸にあるペンダントは……私の、そしてキリトの命を守ってくれたものなの"},"kind":"dialogue"},{"uid":"talk.event_54_04#originalText","id":"talk.event_54_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"在《ALO》里也用弓真的很有诗乃的作风。虽然我自己也是啦。","en":"Using a bow even on ALO sounds like something Sinon would do. I can't say much about other people, but...","ja":"《ALO》でも弓を使うとはシノンらしいな俺も人のことは言えないけど"},"kind":"dialogue"},{"uid":"talk.event_54_05#originalText","id":"talk.event_54_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我觉得小诗诗的话，一定可以很快跟大家打成一片的！","en":"I think Sinon will get along  with everyone in no time!","ja":"シノのんなら、きっとすぐにみんなと仲良くなっちゃうと思うんだ!"},"kind":"dialogue"},{"uid":"talk.event_ch14_01#originalText","id":"talk.event_ch14_01","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"……可是，您要怎么说服其他诸侯呢，阁下？","en":"But...how do you intend to convince the other lords, my lord?","ja":"……しかしどのようにして他の諸侯を説得するおつもりですか、閣下"},"kind":"dialogue"},{"uid":"talk.event_ch14_02#originalText","id":"talk.event_ch14_02","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"不管可不可能，我们无论如何都必须去达成。","en":"Whether it's possible or not, it's something we must do, no matter what.","ja":"可能であろうと無かろうと成さねばならぬのだ。なんとしても"},"kind":"dialogue"},{"uid":"talk.event_ch14_03#originalText","id":"talk.event_ch14_03","speaker":{"cn":"莉琵雅","en":"Lipia","ja":"リピア"},"text":{"cn":"没有……这本来就是我的职责。","en":"No... This is my duty.","ja":"いえ……これがわたくしの役目でございますゆえ"},"kind":"dialogue"},{"uid":"talk.event_ch14_04#originalText","id":"talk.event_ch14_04","speaker":{"cn":"夏斯达","en":"Shasta","ja":"シャスター"},"text":{"cn":"这男人……不明白生命的意义吗？","en":"Does this man...not know life?","ja":"こいつは……この男は命を知らないのか"},"kind":"dialogue"},{"uid":"talk.event_ch14_05#originalText","id":"talk.event_ch14_05","speaker":{"cn":"贝库达","en":"Vecta","ja":"ベクタ"},"text":{"cn":"若想要朕的脑袋，随时都可以从背后偷袭。","en":"Should you want to take my head, feel free to attack me from behind any time.","ja":"余の首を獲りたくばいつでも後ろから斬りかかるがよい"},"kind":"dialogue"},{"uid":"talk.event_58_01#originalText","id":"talk.event_58_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"今天是第一次和雨缘一起远征。要是有足够的体力就好……","en":"Today is my first expedition with Amayori. I hope I have enough strength for it...","ja":"今日は雨縁と初めての遠征でもあります。体力が備わっているとよいのですが……"},"kind":"dialogue"},{"uid":"talk.event_58_02#originalText","id":"talk.event_58_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"和爱丽丝两个人一起出任务真是太让人期待了。赶快做好任务说不定还能聊聊天呢！","en":"I'm looking forward to doing this mission with Alice. If we finish this early, maybe we'll even get a chance to talk!","ja":"アリスとふたりで任務なんて楽しみだなあ。さっさと片付ければ一緒におしゃべりとかできるかも!"},"kind":"dialogue"},{"uid":"talk.event_58_03#originalText","id":"talk.event_58_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在难以活动的地方战斗，果然马上就陷入了苦战。我必须学会更多不同的战斗方法才行。","en":"Just as I thought, it's going to be tough fighting in places with bad footing. I need to learn more ways to fight.","ja":"足場の悪いところでは、やはり苦戦してしまいます。もっと多彩な戦い方を身に着けないと"},"kind":"dialogue"},{"uid":"talk.event_58_04#originalText","id":"talk.event_58_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"爱丽丝果然厉害。在那种难以活动的地方战斗也一次都没有被打中！","en":"Alice truly is amazing. Despite the odds, she didn't let a single strike hit her!","ja":"やっぱりアリスはすごいわあんな足場の悪いところで、ただの一撃も攻撃を受けないんだから!"},"kind":"dialogue"},{"uid":"talk.event_59_01#originalText","id":"talk.event_59_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"听说黑暗界的代表伊斯卡恩曾经和亚丝娜一起战斗过。他是个通情达理的人真是太好了。","en":"As a representative of the Dark Territory, it seems that Iskahn fought alongside Asuna. I'm glad that we can talk with someone who will listen.","ja":"暗黒界の代表・イスカーンはアスナと共闘したらしい話が通じるヤツでよかった"},"kind":"dialogue"},{"uid":"talk.event_59_02#originalText","id":"talk.event_59_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"不管是黑暗界还是人界都必须改变。维持现状的话，早晚会引发更大的战争。","en":"Both the Dark Territory and the Human Empire need to change. If not, eventually another big war will breakout.","ja":"暗黒界も人界も変わらなければならない。そうしないと、いずれまた大きな戦争が起きてしまう"},"kind":"dialogue"},{"uid":"talk.event_59_03#originalText","id":"talk.event_59_03","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"不愧是《绿之剑士》的大哥，所想的事就是和普通人不一样，真有趣。","en":"As expected from the brother of the Green Swordsman! You aren't like the others. But that just makes things even more interesting!","ja":"さすが《緑の剣士》の兄貴だ考えることが普通じゃねえだけど面白えじゃねえか"},"kind":"dialogue"},{"uid":"talk.event_59_04#originalText","id":"talk.event_59_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"要改变人界，首先必须废除公理教会。相对地，需要设立一个行政机关来取代它才行……","en":"If we're going to change the Human Empire, the first thing we need to do is dissolve the Axiom Church. On top of that, we need to form a new government...","ja":"人界を変えるためには、まず公理教会を無くす必要がある。それに変わる行政府をつくらなければ……"},"kind":"dialogue"},{"uid":"talk.event_ch14_06#originalText","id":"talk.event_ch14_06","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"师父，我就相信您会来！","en":"Mentor! I always believed in you!","ja":"師よ、信じておりましたぞ!"},"kind":"dialogue"},{"uid":"talk.event_ch14_07#originalText","id":"talk.event_ch14_07","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"我到底……是怎么看待桐人的……？","en":"What do I think of Kirito?","ja":"私はいったい、キリトのことをどう思っているのだろう……"},"kind":"dialogue"},{"uid":"talk.event_ch14_08#originalText","id":"talk.event_ch14_08","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"大小姐，妳看起来比我想得有精神，我放心了。妳的脸是不是稍微胖了？","en":"Little one. I'm relieved to see you look better than I expected. Have your cheeks filled in a little?","ja":"よう、嬢ちゃん思ったより元気そうで安心したぜちょっと顔がふっくらしたかい?"},"kind":"dialogue"},{"uid":"talk.event_ch14_09#originalText","id":"talk.event_ch14_09","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"我只是想跟他道谢。我想感谢他和我战斗，并把我打倒。","en":"I just want to thank him. For fighting and defeating me.","ja":"ただひと言、お礼が言いたいの私と戦い、倒してくれたことにね"},"kind":"dialogue"},{"uid":"talk.event_ch14_10#originalText","id":"talk.event_ch14_10","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"我们一定会保护桐人学长。","en":"We promise to protect Kirito, no matter what.","ja":"必ず、私たちがキリト先輩を守り抜きます"},"kind":"dialogue"},{"uid":"talk.event_ch15_1_01#originalText","id":"talk.event_ch15_1_01","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"喔……《最终负荷实验》吗？连好莱坞电影都相形失色呢。","en":"The final load test, huh? This puts even Hollywood movies to shame!","ja":"ウォウ……《最終負荷実験》かこいつはハリウッド・ムービーも形無しだな"},"kind":"dialogue"},{"uid":"talk.event_ch15_1_02#originalText","id":"talk.event_ch15_1_02","speaker":{"cn":"加百列","en":"Gabriel","ja":"ガブリエル"},"text":{"cn":"暗之国的将兵们！你们期待已久的时刻到来了！──蹂躏他们！","en":"Soldiers of the land of darkness! The time you have long awaited is nigh!  Lay waste to this land!","ja":"闇の国の将兵どもよ!貴様らが待ち望んだ刻が来た!――蹂躙せよ!"},"kind":"dialogue"},{"uid":"talk.event_ch15_1_03#originalText","id":"talk.event_ch15_1_03","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"第一部队，拔剑，准备战斗！修士队，准备咏唱治愈术！","en":"First unit, draw your swords! Prepare for battle! Monk unit, ready your healing arts and incantations!","ja":"第一部隊、抜剣、戦闘用意!修道士隊、治癒術詠唱用意!"},"kind":"dialogue"},{"uid":"talk.event_ch15_1_04#originalText","id":"talk.event_ch15_1_04","speaker":{"cn":"迪索尔巴德","en":"Deusolbert","ja":"デュソルバート"},"text":{"cn":"……来了吗。","en":"They're coming...","ja":"……来るか"},"kind":"dialogue"},{"uid":"talk.event_ch15_1_05#originalText","id":"talk.event_ch15_1_05","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"可恶的暗之民……让你们见识一下我的实力。","en":"You cursed dwellers of the darkness. We'll show you what we're made of! ","ja":"闇の輩どもめ目に物見せてくれよう"},"kind":"dialogue"},{"uid":"talk.event_ch15_2_01#originalText","id":"talk.event_ch15_2_01","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"为什么哥布尔已经攻进这种地方来了？","en":"Why are the goblins this far back?","ja":"なんで、こんなところまでゴブリンが攻めてきてるのさ?"},"kind":"dialogue"},{"uid":"talk.event_ch15_2_02#originalText","id":"talk.event_ch15_2_02","speaker":{"cn":"里涅尔","en":"Linel","ja":"リネル"},"text":{"cn":"负责守前面的连利仔在做什么！？","en":"Why isn't Renlicchi defending the area ahead like he's supposed to?!","ja":"この前を守ってるはずのレンリっちは何してるの!?"},"kind":"dialogue"},{"uid":"talk.event_ch15_2_03#originalText","id":"talk.event_ch15_2_03","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"……快站起来，该回到岗位上了。","en":"Get up. You have to go back to your position.","ja":"……立つんだ持ち場に戻らなきゃ"},"kind":"dialogue"},{"uid":"talk.event_ch15_2_04#originalText","id":"talk.event_ch15_2_04","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"将学长藏进里面，我们在外面守着入口吧。","en":"Let's hide him in the back and guard the entrance.","ja":"先輩を奥に隠して、あたしたちは入り口を守りましょう"},"kind":"dialogue"},{"uid":"talk.event_ch15_2_05#originalText","id":"talk.event_ch15_2_05","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"骑士大人，我知道这是任性的请求，可以请您帮帮我们吗？","en":"Sir Knight, forgive me if I'm being forward, but would you be so kind as to help us out?","ja":"騎士さま、勝手なことを申すようですが、どうか私たちに手を貸してくださいませんか?"},"kind":"dialogue"},{"uid":"talk.event_ch16_1_01#originalText","id":"talk.event_ch16_1_01","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这气息不是来自暗黑骑士的飞龙，而是发自更为冰冷的米尼翁们。","en":"This presence I sense... It's not the dragons of the Dark Knights. It's much colder...minions.","ja":"この気配は、暗黒騎士の飛竜じゃねぇもっと冷たい、ミニオンどもの気配だ"},"kind":"dialogue"},{"uid":"talk.event_ch16_1_02#originalText","id":"talk.event_ch16_1_02","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"──我很冷静。现在正是抓住荣光的最佳时机。","en":"I am calm. Now is the time to seize my first glory.","ja":"――私は冷静だいまこそ、最初の栄光を掴み取る時"},"kind":"dialogue"},{"uid":"talk.event_ch16_1_03#originalText","id":"talk.event_ch16_1_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"为什么不只人界人，连亚人灵魂产生的神圣力都这么温暖纯净呢……","en":"...but also the souls of the demi- humans, are generating a sacred power that's so warm and pure?","ja":"なぜ人界人だけでなく亜人の魂から生まれてくる神聖力もそのすべてが温かく清らかなの……"},"kind":"dialogue"},{"uid":"talk.event_ch16_1_04#originalText","id":"talk.event_ch16_1_04","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"暴露出那么愚蠢……狼狈的模样……简直就是活生生的耻辱……我算什么骑士……！","en":"So stupid...so miserable... so humiliating... A disgrace of a knight...","ja":"愚かな……無様な姿を……生き恥をさらして……何が騎士か"},"kind":"dialogue"},{"uid":"talk.event_ch16_1_05#originalText","id":"talk.event_ch16_1_05","speaker":{"cn":"贝库达","en":"Vecta","ja":"ベクタ"},"text":{"cn":"血与……命吗？","en":"Blood...and life, huh?","ja":"血と……命か"},"kind":"dialogue"},{"uid":"talk.event_ch16_2_01#originalText","id":"talk.event_ch16_2_01","speaker":{"cn":"蒂伊‧艾‧耶尔","en":"Dee Eye Ell","ja":"ディー・アイ・エル"},"text":{"cn":"半兽人的首领，利鲁匹林。为了暗黑术师施放攻击法术所需的力量来源，凑出三千名祭品吧。","en":"Orc Chief Lilpilin. You're to offer 3,000 sacrifices to be the foundation of the dark mages' attack art.","ja":"オークの長、リルピリンよ暗黒術師の攻撃術の礎となるために3000の人柱を拠出せよ"},"kind":"dialogue"},{"uid":"talk.event_ch16_2_02#originalText","id":"talk.event_ch16_2_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"那个是……那些家伙……居然做出这种事！","en":"Those bastards... What have they done?!","ja":"あれは……奴ら……なんて真似を!"},"kind":"dialogue"},{"uid":"talk.event_ch16_2_03#originalText","id":"talk.event_ch16_2_03","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我到底在迷茫些什么？实在是太小心眼了……","en":"What had me so confused? What tiny, insignificant things...","ja":"私は、何を迷っていたのかなんてちっぽけな……"},"kind":"dialogue"},{"uid":"talk.event_ch16_2_04#originalText","id":"talk.event_ch16_2_04","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"我要守护她。我的师父，爱丽丝大人。她是我献上剑并誓言要为之舍身的人，无论如何都得守护她！","en":"On my life, I will save you. My Mentor. Lady Alice... Everyone who pledged their swords, their lives... I must save them all!","ja":"守る。師を。アリス様を剣を捧げ、献身を誓った人を何としても守らねば!"},"kind":"dialogue"},{"uid":"talk.event_ch16_2_05#originalText","id":"talk.event_ch16_2_05","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"你们做出这种事，可别以为能够全身而退！！！","en":"After all the havoc you've wreaked... don't think you're not going to pay!","ja":"これだけのことをしてよもやただで済むと思うまいな!!!"},"kind":"dialogue"},{"uid":"talk.event_60_01#originalText","id":"talk.event_60_01","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"虽然损失惨重……我们仍必须努力向前迈进。","en":"We suffered many losses... but we must be  forward-thinking.","ja":"失ってしまったものは大きいけれど……私たちは、前を向かねばなりません"},"kind":"dialogue"},{"uid":"talk.event_60_02#originalText","id":"talk.event_60_02","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"我对于解散公理教会有异议！","en":"I am opposed to dismantling the Axiom Church!","ja":"公理教会を解体することに異議を唱える!"},"kind":"dialogue"},{"uid":"talk.event_60_03#originalText","id":"talk.event_60_03","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"如果实力强的家伙比较伟大，那不就跟暗之国的《力量铁则》没什么不同了吗？","en":"But is having only the strongest lead us any different from the Dark Realm's \"Law of Power\"?","ja":"強いヤツがエラいっちゅうなら闇の国の《力の掟》とかいうのと同じと違いますか?"},"kind":"dialogue"},{"uid":"talk.event_60_04#originalText","id":"talk.event_60_04","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"没错，我们之间不需要客气。因为我是你的指导生啊。","en":"That's right.  Don't ever hold back on our account. I'm your mentor after all, Kirito.","ja":"私たちの間に、遠慮などというものは不要だ私はお前の指導生なのだからな"},"kind":"dialogue"},{"uid":"talk.event_60_05#originalText","id":"talk.event_60_05","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我也会感到不安，但是跟亚丝娜在一起的话，我就觉得没问题。","en":"I do feel uneasy about a few things. But we're stronger together.","ja":"不安もあるけど、アスナが一緒なら俺は大丈夫だと思う"},"kind":"dialogue"},{"uid":"talk.event_61_01#originalText","id":"talk.event_61_01","speaker":{"cn":"费赛尔","en":"Fizel","ja":"フィゼル"},"text":{"cn":"安全上垒！桐人，我们安全上垒了对不对！","en":"Annnd we made it! We made it, right Kirito?","ja":"ギリギリセーフ!ねえ、セーフだよね、キリト!"},"kind":"dialogue"},{"uid":"talk.event_61_02#originalText","id":"talk.event_61_02","speaker":{"cn":"库鲁加","en":"Cruiga","ja":"クルーガ"},"text":{"cn":"……不用再说了。朕就是在说那都是一派胡言。你们对经世治民一无所知。","en":"This is a waste of breath. And I'm telling you, that's gibberish. You don't know the first thing about ruling.","ja":"……話にならぬな人を治める、ということをわかっておらぬ"},"kind":"dialogue"},{"uid":"talk.event_61_03#originalText","id":"talk.event_61_03","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"强硬手段……又要打仗了吗？","en":"Tough action? Do you mean...more war?","ja":"強硬策って、また戦争……ですか"},"kind":"dialogue"},{"uid":"talk.event_61_04#originalText","id":"talk.event_61_04","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"现在就剩你一个人了，库鲁加‧诺兰卡鲁斯！","en":"No one's left to defend you now, Cruiga Norlangarth!","ja":"これであなたひとりよクルーガ・ノーランガルス!"},"kind":"dialogue"},{"uid":"talk.event_61_05#originalText","id":"talk.event_61_05","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个人界的确很美好。但是，也有许多不平等的地方。","en":"The Human Empire is indeed great. But in many areas, it's filled with inequities.","ja":"この人界は、確かに素晴らしいでも、不平等に歪んでいるところもあるんだ"},"kind":"dialogue"},{"uid":"talk.event_66_01#originalText","id":"talk.event_66_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人，你果然还是独行侠呢。明明越往高层移动，单人攻略的难度就会越高……","en":"There goes Kirito again, solo as always. Even though the higher the floor we go up, the more dangerous it gets...","ja":"キリトくん、相変わらずソロなのね高層に行けば行くほど危険は増すっていうのに……"},"kind":"dialogue"},{"uid":"talk.event_66_02#originalText","id":"talk.event_66_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"这个地方很不错。暂时就把这里当成据点吧。","en":"This town ain't too shabby. I should probably set up base here.","ja":"この街は、なかなか良さそうだなしばらくここを本拠地にしてみるか"},"kind":"dialogue"},{"uid":"talk.event_66_03#originalText","id":"talk.event_66_03","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"呵呵，我今天有一个能让桐人大吃一惊的计划喔！","en":"Hehe. Today I've got a plan that will knock Kirito off his socks!","ja":"ふふ、今日はキリトくんをびっくりさせる作戦があるんだ！"},"kind":"dialogue"},{"uid":"talk.event_66_04#originalText","id":"talk.event_66_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"《两个人的纪念碑》……怎么看都很可疑，但调查过后也什么都没发现。","en":"Monument for Two... This thing really is  mysterious. Nothing comes up even when I try looking it up.","ja":"《ふたりの記念碑》……いかにも怪しいんだけど調べても何も出てこないんだよなあ"},"kind":"dialogue"},{"uid":"talk.event_66_05#originalText","id":"talk.event_66_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"吃东西这个行为，就算是在VR世界里，也是非常重要。这是桐人教会我的。","en":"Even in the VR world, Kirito taught me that eating is a very important thing to do.","ja":"食べるっていう行為は、VRの世界であっても、とても大切なことキリトくんがそれを教えてくれたの"},"kind":"dialogue"},{"uid":"talk.event_ch17_1_01#originalText","id":"talk.event_ch17_1_01","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"那个暗神贝库达看来真的很想得到大小姐啊。他似乎打算派全军追过来。","en":"The Dark God Vecta sure seems obsessed with you. He's planning to come after you with his entire army.","ja":"暗黒神ベクタとやらは、ずいぶんと嬢ちゃんにご執心のようだな全軍で追っかけてくるらしいぞ"},"kind":"dialogue"},{"uid":"talk.event_ch17_1_02#originalText","id":"talk.event_ch17_1_02","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"太好了，终于轮到我们出场了吗！！竟然让我们等这么久。要上啰，大伙！","en":"Alright, it's our turn to shine! It's about damn time! Let's go!","ja":"よぉぉし、やっと出番か!!ずいぶん待たせやがって行くぞ、お前ら!"},"kind":"dialogue"},{"uid":"talk.event_ch17_1_03#originalText","id":"talk.event_ch17_1_03","speaker":{"cn":"谢达","en":"Sheyta","ja":"シェータ"},"text":{"cn":"……我是为了不让你通过这里而来的。","en":"I'm here... to keep you from advancing.","ja":"……私は、あなたを通さないためにここにいます"},"kind":"dialogue"},{"uid":"talk.event_ch17_1_04#originalText","id":"talk.event_ch17_1_04","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……因为学长教我别依赖眼睛，要用全身去感受。","en":"My mentor taught me not to rely on my eyes, but to sense everything.","ja":"……眼だけに頼るな全体を感じろって先輩が教えてくれたから"},"kind":"dialogue"},{"uid":"talk.event_ch17_1_05#originalText","id":"talk.event_ch17_1_05","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"──就是这个感觉，用我的剑锋玩弄他人的性命和羁绊真是太愉悦了。就是这样我才戒不掉杀玩家的习惯。","en":"The pleasure of playing with someone's life with the tip of my sword...I love it! No wonder I can't stop!","ja":"――これだよ、この感じ人の命を、絆を剣先で弄ぶこの愉悦これだからPKはやめられねぇ"},"kind":"dialogue"},{"uid":"talk.event_ch17_2_01#originalText","id":"talk.event_ch17_2_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人深爱并生活过的这个世界，就由我来守护。不会让神秘的袭击者乱来……也不会让RATH为所欲为。","en":"I'll protect this world that Kirito loved and lived in. From those intruders...and from Rath, too.","ja":"キリトくんが愛し、生きた世界はわたしが守る。謎の襲撃者たちから……そして、ラースからも"},"kind":"dialogue"},{"uid":"talk.event_ch17_2_02#originalText","id":"talk.event_ch17_2_02","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"这个女人，对桐人表现出很不自然的过分亲暱……她一定是为了要拢络桐人，想将桐人带去暗之国的间谍！","en":"This girl seems awfully friendly with Kirito. She's a temptress, sent here by the enemy to take Kirito. I just know it!","ja":"この女、キリトに対して不自然なほど馴れ馴れしい……。キリトを籠絡し闇の国へ連れ去る間者に決まっている!"},"kind":"dialogue"},{"uid":"talk.event_ch17_2_03#originalText","id":"talk.event_ch17_2_03","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"唔～真是精彩的一幕啊。艳丽绽放的两朵鲜花，简直堪称美景啊。","en":"Hmm, now this is truly a splendid sight to see. Two beautiful flowers bursting into bloom. It's glorious.","ja":"うーむ、こりゃあ実になんとも、見事な眺めだな咲き誇る麗しき花二輪、いや絶景絶景"},"kind":"dialogue"},{"uid":"talk.event_ch17_2_04#originalText","id":"talk.event_ch17_2_04","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……他可是我的学长啊……","en":"He's my mentor, you know...","ja":"……私の先輩、なんだもん……"},"kind":"dialogue"},{"uid":"talk.event_ch17_2_05#originalText","id":"talk.event_ch17_2_05","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"我和桐人也有不浅的缘分。才会忍不住加入这场讨论会。","en":"Since I also, have a close relationship  with Kirito, I couldn't stop myself from coming here.","ja":"私もキリトとは浅からぬ縁があるゆえ我慢しきれず参上した次第です"},"kind":"dialogue"},{"uid":"talk.event_67_01#originalText","id":"talk.event_67_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"黑暗领域比我想像中荒废得还要严重……","en":"The Dark Territory is in even worse shape than I thought...","ja":"ダークテリトリーの荒廃は思った以上にひどいな……"},"kind":"dialogue"},{"uid":"talk.event_67_02#originalText","id":"talk.event_67_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"莉法很受半兽人族欢迎呢。特别是那个利鲁匹林……","en":"Leafa is fairly respected by the orc tribe. Especially by that Lilpilin...","ja":"リーファはずいぶんとオーク族に慕われているようだな。特にあのリルピリンには……"},"kind":"dialogue"},{"uid":"talk.event_67_03#originalText","id":"talk.event_67_03","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"《绿之剑士》莉法不仅救了我们半兽人族的性命，更是拯救了我们灵魂的女神。","en":"Leafa, the Green Swordsman, is a goddess who saved not only our tribe, but our souls as well.","ja":"《緑の剣士》リーファはオーク族の命だけでなく魂も救っでくれだ女神なんだ"},"kind":"dialogue"},{"uid":"talk.event_67_04#originalText","id":"talk.event_67_04","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"都是因为战争，现在能够跟这附近的魔兽战斗的战士也没几个了。","en":"Because of the war, we have very few warriors who can battle the magical beasts who frequent nearby.","ja":"戦争のせいで、近隣に出没する魔獣と戦える戦士が少ないんだ"},"kind":"dialogue"},{"uid":"talk.event_67_05#originalText","id":"talk.event_67_05","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"能够跟黑暗界和平共处，也是托利鲁匹林和莉法的福，真的要好好感谢他们。","en":"It's thanks to Lilpilin and Leafa that peace between the Dark Territory is a success. We need to thank them!","ja":"暗黒界との和平がすんなりいったのもリルピリンとリーファのおかげだな感謝しないと"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_01#originalText","id":"talk.event_ch18_1_01","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这是战争。必须活用这个机会才行……","en":"This is war. We have to take this chance.","ja":"こいつは戦争だこの機は……活かさねばならん"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_02#originalText","id":"talk.event_ch18_1_02","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"这就是……这就是战争吗？这种情况算得上是战斗吗？","en":"So this...so this is war, huh? How can you call this a battle?","ja":"これが……これが、戦かよこんなものが、闘いと呼べるのか"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_03#originalText","id":"talk.event_ch18_1_03","speaker":{"cn":"克里达","en":"Critter","ja":"クリッター"},"text":{"cn":"我会给你们暗黑骑士的帐号。你们就尽情杀戮人界军那些家伙吧！","en":"Use the dark knight accounts. Go on and massacre the Human Empire Army to your heart's content!","ja":"お前らに暗黒騎士のアカウントをくれてやる。存分に、人界軍の連中を蹂躙してやりな!"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_04#originalText","id":"talk.event_ch18_1_04","speaker":{"cn":"结衣","en":"Yui","ja":"ユイ"},"text":{"cn":"糟了……爸爸和妈妈……有危险了！","en":"Oh, no! Daddy and Mommy are in danger!","ja":"大変……パパとママが、危ない!"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_05#originalText","id":"talk.event_ch18_1_05","speaker":{"cn":"莉兹贝特","en":"Lisbeth","ja":"リズベット"},"text":{"cn":"拜托了，为了守护他们，请大家借给我力量！","en":"Please lend us a hand to protect them!","ja":"お願いです、彼らを守るためにみんなの力を貸して!"},"kind":"dialogue"},{"uid":"talk.event_ch18_1_06#originalText","id":"talk.event_ch18_1_06","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"敌人的数量……实在太多了……照这样下去……","en":"There's too many... We can't win...","ja":"数が……数が多すぎる……このままじゃ……"},"kind":"dialogue"},{"uid":"talk.event_story62_01#originalText","id":"talk.event_story62_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"黑暗界一定比人界更广阔吧～但听说不毛之地也很多。","en":"The Dark Territory is way bigger than the Human Empire. But a lot of it looks barren.","ja":"暗黒界って人界よりもずいぶん広いのねーでも、荒れ地が多いみたい"},"kind":"dialogue"},{"uid":"talk.event_story62_02#originalText","id":"talk.event_story62_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"虽说莉琵雅也是，其实黑暗界的人和人界的一样，有好人的同时也有奇怪的人呢。","en":"This applies to Lipia too, but people from the Dark Territory are just like people in the Human Empire; if there are good people, then that means there are also weirdos.","ja":"リピアもそうだったけど暗黒界の人も人界と同じでいい人もいれば変な人もいるのね"},"kind":"dialogue"},{"uid":"talk.event_story62_03#originalText","id":"talk.event_story62_03","speaker":{"cn":"连基尔","en":"Rengil","ja":"レンギル"},"text":{"cn":"你、你说人界的和平！？我的商工公会到底会变成怎样……？","en":"P-Peace with the Human Empire?! What in the world will happen to my Commerce Guild...?","ja":"じ、人界と和平だと!?私の商工ギルドはいったいどうなってしまうのだ……?"},"kind":"dialogue"},{"uid":"talk.event_story62_04#originalText","id":"talk.event_story62_04","speaker":{"cn":"夏莉","en":"Shirley","ja":"シャーリー"},"text":{"cn":"孤儿院的大家就由我来守护！莉琵雅大人曾经叫过我要这样做的！","en":"I will protect everyone in the Orphanage! Lady Lipia charged me with that duty!","ja":"孤児院のみんなは、わたしが守る!リピア様がわたしに任せてくださったんだ!"},"kind":"dialogue"},{"uid":"talk.event_story62_05#originalText","id":"talk.event_story62_05","speaker":{"cn":"夏莉","en":"Shirley","ja":"シャーリー"},"text":{"cn":"这种地方竟然有人界人来……？说不定，她比起魔物还更麻烦呢。","en":"People from the Human Empire are going to come to a place like this...? This might be more troublesome than having Fiends running around.","ja":"こんな所に人界人が来るなんて……?もしかしたら、魔物よりもやっかいかもしれないわ"},"kind":"dialogue"},{"uid":"talk.event_story68_01#originalText","id":"talk.event_story68_01","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"如果皇帝只是一个会让民众受苦的存在，那么民众根本就不需要皇帝了吧。","en":"If his role is to only make the people suffer, then I see no reason as to why there should be an emperor!","ja":"民衆を苦しめるだけの存在だとしたら皇帝なんてものはいらないんじゃないか"},"kind":"dialogue"},{"uid":"talk.event_story68_02#originalText","id":"talk.event_story68_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"《四帝国大乱》结束之后，连利变得很可靠。也感觉比以前更有自信。","en":"After the uprising in the Four Empires finished, I knew could count on Renly. I feel like he has more confidence than before.","ja":"《四帝国の大乱》が終わってからレンリは頼もしくなった。以前より自分に自信を持っている気がする"},"kind":"dialogue"},{"uid":"talk.event_story68_03#originalText","id":"talk.event_story68_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"让央都的人也帮忙修复圣堂吧。","en":"Let's ask people from Centoria to help with the repairs on the Cathedral.","ja":"カセドラルの修復は央都の人に手伝ってもらおう"},"kind":"dialogue"},{"uid":"talk.event_story68_04#originalText","id":"talk.event_story68_04","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"托尔贾修‧萨查库罗伊斯……怎么能因为是自己的直辖地区就如此为所欲为！","en":"Tolgash Southacroith... Don't think you can get away with doing whatever you wish even if it's your territory!","ja":"トルガシュ・サザークロイス……自らの直轄地だからといって何でもしていいわけじゃない!"},"kind":"dialogue"},{"uid":"talk.event_ch18_2_01#originalText","id":"talk.event_ch18_2_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"──够了。这根本不是战争。","en":"I hate this... This isn't a fair battle.","ja":"――もう嫌だこんなのは戦いではない"},"kind":"dialogue"},{"uid":"talk.event_ch18_2_02#originalText","id":"talk.event_ch18_2_02","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"帮我转告那个混帐，我们才不是你的玩偶。","en":"To let that bastard know that we're not his damned puppets!","ja":"野郎に、教えてやってくれ俺たちは、てめぇの人形じゃねえってな"},"kind":"dialogue"},{"uid":"talk.event_ch18_2_03#originalText","id":"talk.event_ch18_2_03","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"我这边还有一个……特别的珍藏帐号。","en":"I have an account. A real special one.","ja":"アカウントならあるぜとっておきのヤツが"},"kind":"dialogue"},{"uid":"talk.event_ch18_2_04#originalText","id":"talk.event_ch18_2_04","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"那是谁……？妳到底是谁？","en":"Who... Who are you?","ja":"誰……?あなたは、誰なの?"},"kind":"dialogue"},{"uid":"talk.event_ch18_2_05#originalText","id":"talk.event_ch18_2_05","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"对哦……有啊，的确有啊！有数据可以补完桐人小弟被毁掉的主体！","en":"That's right! We have it. We have data we can use to restore Kirito's shattered subject!","ja":"そうか……ある、あるッスよキリト君の、吹っ飛ばされちまった主体を補完できるデータが!"},"kind":"dialogue"},{"uid":"talk.event_story63_01#originalText","id":"talk.event_story63_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"那个叫夏莉的孩子真的跟莉琵雅一模一样。而且……总觉得莫名地让人怀念啊。","en":"That Shirley sure does resemble Lipia. ... It kind of takes me back.","ja":"シャーリーっていう子、本当にリピアにそっくり。それに……なぜか、懐かしい感じもするの"},"kind":"dialogue"},{"uid":"talk.event_story63_02#originalText","id":"talk.event_story63_02","speaker":{"cn":"夏莉","en":"Shirley","ja":"シャーリー"},"text":{"cn":"守护这家孤儿院是我的任务！可不能全交由人界人伊迪丝负责！","en":"Protecting this Orphanage is my mission! I can't rely on only Eydis for everything!","ja":"この孤児院を守るのは、わたしの任務なんだ! 人界人のイーディスにばっかり任せてられない!"},"kind":"dialogue"},{"uid":"talk.event_story63_03#originalText","id":"talk.event_story63_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"强力的魔物……吗？有必要调查一下呢。","en":"Powerful monsters, huh...? Well we'll have to look into that then.","ja":"強力な魔物……か調べてみないとね"},"kind":"dialogue"},{"uid":"talk.event_story63_04#originalText","id":"talk.event_story63_04","speaker":{"cn":"夏莉","en":"Shirley","ja":"シャーリー"},"text":{"cn":"对面那座山是山地哥布尔的领地。但是，听说那里有魔物的巢穴……","en":"The mountains over there is Mountain Goblin territory. But, rumor is that the monster's nest is right over there...","ja":"向こうの山は山ゴブリンの領地なんだでも、そこに魔物の巣があるっていう噂が……"},"kind":"dialogue"},{"uid":"talk.event_ch19_1_01#originalText","id":"talk.event_ch19_1_01","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"为什么追不上？我都已经轮流骑乘三头飞龙了。","en":"Why aren't I catching up? Even though I'm switching between three different dragons?","ja":"なぜ追いつけんこっちは3頭を乗り換えてるってのに"},"kind":"dialogue"},{"uid":"talk.event_ch19_1_02#originalText","id":"talk.event_ch19_1_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"……你这家伙能吞噬人的心意吗？","en":"So you can devour people's Incarnation?","ja":"……貴様は、人の心意を喰うのか"},"kind":"dialogue"},{"uid":"talk.event_ch19_1_03#originalText","id":"talk.event_ch19_1_03","speaker":{"cn":"贝库达","en":"Vecta","ja":"ベクタ"},"text":{"cn":"心意？……原来如此，是指心灵和意念吗？","en":"Incarnation? I see. Mind and will, huh?","ja":"シンイ?……なるほど、マインドとウィルか"},"kind":"dialogue"},{"uid":"talk.event_ch19_1_04#originalText","id":"talk.event_ch19_1_04","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"那家伙、还有这家伙也是……到处都是令人怀念的熟面孔啊。","en":"Look at him...and her... What a collection of familiar faces.","ja":"アイツも、コイツも……ずいぶん懐かしい顔ぶれが揃ってるじゃねえか"},"kind":"dialogue"},{"uid":"talk.event_ch19_1_05#originalText","id":"talk.event_ch19_1_05","speaker":{"cn":"克莱因","en":"Klein","ja":"クライン"},"text":{"cn":"不……不会吧。不可能啊，怎么会……我看到……亡灵了吗……？","en":"No...it can't be. There's just no way! Am I seeing a ghost?","ja":"いや……まさかありえねぇよ、そんな……亡霊を……見てるのか……?"},"kind":"dialogue"},{"uid":"talk.event_ch19_2_01#originalText","id":"talk.event_ch19_2_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"妳说叔叔他……不惜牺牲生命也要跟他同归于尽的敌人并没有死！？","en":"So the man that Uncle sacrificed himself to kill isn't dead?!","ja":"小父様が……命を捨ててまで刺し違えた敵が死んでいないと!?"},"kind":"dialogue"},{"uid":"talk.event_ch19_2_02#originalText","id":"talk.event_ch19_2_02","speaker":{"cn":"诗乃","en":"Sinon","ja":"シノン"},"text":{"cn":"不会有错，我认识他。我看过这双眼睛……认识这张面孔。","en":"There's no doubt... I know him! Those eyes... that face...!","ja":"間違いない、知っている私はこの眼を……この顔を知っている"},"kind":"dialogue"},{"uid":"talk.event_ch19_2_03#originalText","id":"talk.event_ch19_2_03","speaker":{"cn":"Subtilizer","en":"Subtilizer","ja":"サトライザー"},"text":{"cn":"这是命运，是灵魂的力量让我跟妳在此重逢。","en":"This is fate. It is the power of our souls that attract them to each other.","ja":"これは運命さ私と君を引きつけ合う魂の力なのだ"},"kind":"dialogue"},{"uid":"talk.event_ch19_2_04#originalText","id":"talk.event_ch19_2_04","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"就是你将爱丽丝计划的情报泄漏给美国人的吧！","en":"You're the one who's been leaking information about Project Alicization to the Americans!","ja":"あんたがアメリカ人にアリシゼーション計画の情報を流していたんスね!"},"kind":"dialogue"},{"uid":"talk.event_ch19_2_05#originalText","id":"talk.event_ch19_2_05","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"啊，一开始的地方有注释。……《Code871》？871是什么？","en":"Oh, something's commented out near the beginning. \"Code 871\"? What's 871?","ja":"あ、最初のとこにコメントアウトがあるわ……《コード871》?　871って何?"},"kind":"dialogue"},{"uid":"talk.event_story64_01#originalText","id":"talk.event_story64_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"夏莉，非常有潜力耶。多加锻炼一定能变得更强的。","en":"I have high expecations for Shirley! If she keeps at it, she'll be quite the fighter.","ja":"シャーリー、かなり見込みがあるわね鍛えればもっとずっと強くなりそう"},"kind":"dialogue"},{"uid":"talk.event_story64_02#originalText","id":"talk.event_story64_02","speaker":{"cn":"黑袍男","en":"Black-Robed Man","ja":"黒ローブの男"},"text":{"cn":"那位女骑士还有同行的少女……似乎可以成为不错的「材料」。","en":"That girl with the knight is exactly what I'm looking for!","ja":"あの女騎士と一緒にいる少女……あれならいい「素材」になりそうです"},"kind":"dialogue"},{"uid":"talk.event_story64_03#originalText","id":"talk.event_story64_03","speaker":{"cn":"夏莉","en":"Shirley","ja":"シャーリー"},"text":{"cn":"等我变得更强之后……我绝对会打倒妳的！","en":"I am gonna beat you someday, Eydis! Just need to get a little bit stronger first!","ja":"もっと、強くなったら……イーディスのことはわたしが絶対倒すから!"},"kind":"dialogue"},{"uid":"talk.event_story64_04#originalText","id":"talk.event_story64_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"刚刚的尖叫声……夏莉，等等我现在就去救妳！","en":"Was that a scream?! Hold on, Shirley! I'm on my way!","ja":"今の悲鳴……シャーリー、待っててすぐに助ける!"},"kind":"dialogue"},{"uid":"talk.event_ch20_1_01#originalText","id":"talk.event_ch20_1_01","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"啊啊……可恶……我真想跟妳组一个家庭，一定可以生出很强的小子。","en":"Dammit... I wish I could've had a family with you. What a strong kid we would've had.","ja":"ああ……ちきしょうアンタと、所帯を持ちたかったなきっと、強ぇガキが生まれたろうにな"},"kind":"dialogue"},{"uid":"talk.event_ch20_1_02#originalText","id":"talk.event_ch20_1_02","speaker":{"cn":"莉法","en":"Leafa","ja":"リーファ"},"text":{"cn":"不用担心……那种家伙不管来几万人，我都不会输的！","en":"Don't worry... I don't care how many of them there are, I won't lose!","ja":"大丈夫……あんな奴ら、何万人いたって負けないわ!"},"kind":"dialogue"},{"uid":"talk.event_ch20_1_03#originalText","id":"talk.event_ch20_1_03","speaker":{"cn":"连利","en":"Renly","ja":"レンリ"},"text":{"cn":"我会保护妳们……绝对不要离开我身边。","en":"I will protect you. Make sure that you do not leave my side.","ja":"君たちは僕が守るから……絶対に、僕から離れないで"},"kind":"dialogue"},{"uid":"talk.event_ch20_1_04#originalText","id":"talk.event_ch20_1_04","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"快丢下武器投降。只要这么做，我就不杀你们和后面的俘虏。","en":"Lay down your weapons and surrender. Do that, and I won't kill you and those behind you.","ja":"武器を捨てて投降しろそうすれば、お前らも後ろの捕虜も殺しはしない"},"kind":"dialogue"},{"uid":"talk.event_ch20_1_05#originalText","id":"talk.event_ch20_1_05","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"这是……复仇吗？报复我们攻略组那时摧毁了微笑棺木吗……？","en":"Is this...vengeance? For the Assault Team wiping out Laughing Coffin?","ja":"これは……復讐なの?ラフィン・コフィンを壊滅させたわたしたち攻略組への……?"},"kind":"dialogue"},{"uid":"talk.event_ch20_2_01#originalText","id":"talk.event_ch20_2_01","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"喂，黑漆漆的，快起来。有听到吗？黑色剑士大人？","en":"Hey, Blackie, wake up. You hear me, Mr. Black Swordsman?","ja":"おいブラッキー、起きろよ?聞こえてんのか、黒の剣士サマよ?"},"kind":"dialogue"},{"uid":"talk.event_ch20_2_02#originalText","id":"talk.event_ch20_2_02","speaker":{"cn":"YUNA","en":"Yuna","ja":"ユナ"},"text":{"cn":"我们上吧，瑛二。","en":"Let's do this, Eiji!","ja":"行くわよ、エイジ"},"kind":"dialogue"},{"uid":"talk.event_ch20_2_03#originalText","id":"talk.event_ch20_2_03","speaker":{"cn":"瑛二","en":"Eiji","ja":"エイジ"},"text":{"cn":"我是……血盟骑士团的《鹦鹉螺》！","en":"I'm...the Knights of the Blood Oath's Nautilus!","ja":"僕は……血盟騎士団の《ノーチラス》だ!"},"kind":"dialogue"},{"uid":"talk.event_ch20_2_04#originalText","id":"talk.event_ch20_2_04","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"比嘉，快躲开！！","en":"Higa, watch out!","ja":"比嘉君、避けて!!"},"kind":"dialogue"},{"uid":"talk.event_ch20_2_05#originalText","id":"talk.event_ch20_2_05","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"──好了，桐人小弟，差不多该起来啰。","en":"All right, Kirito. Time to wake up.","ja":"――よし、キリト君そろそろ起きる時間だぜ"},"kind":"dialogue"},{"uid":"talk.event_story65_01#originalText","id":"talk.event_story65_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"比我预料的还要早结婚耶！只是我本来以为婚礼应该会办得跟人界一样更盛大一点什么的。","en":"They got married pretty quick! I actually thought that they were going to have a big party.","ja":"ずいぶん早く結婚したわねもうちょっと派手に、人界と一緒にわーって騒ぐと思ったんだけど"},"kind":"dialogue"},{"uid":"talk.event_story65_02#originalText","id":"talk.event_story65_02","speaker":{"cn":"伊斯卡恩","en":"Iskahn","ja":"イスカーン"},"text":{"cn":"巨人族的叛乱有点麻烦啊……当然我们绝对不会输，但也会造成伤亡，因此进退两难。","en":"The giants' rebellion is a real nuisance...Of course we won't lose, but there will be losses.","ja":"ジャイアントの叛乱は厄介だ……もちろん負けはしねえが犠牲を少なくしようと思うと難しい"},"kind":"dialogue"},{"uid":"talk.event_story65_03#originalText","id":"talk.event_story65_03","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"竟敢妨碍两人的结婚典礼，我绝对饶不了他们！就用我的这把剑来击退他们！","en":"I'll make sure nobody causes a ruckus at your ceremony! Me and my blade will make sure of that!","ja":"ふたりの結婚式を邪魔するなんて……絶対に許せない!あたしがこの剣でぶった斬るんだから！"},"kind":"dialogue"},{"uid":"talk.event_story65_04#originalText","id":"talk.event_story65_04","speaker":{"cn":"利鲁匹林","en":"Lilpilin","ja":"リルピリン"},"text":{"cn":"右眼的伤，是我和莉法的羁绊，被摧毁的右眼已成为我的勋章了。","en":"This scar on my right eye is my connection with Leafa.  It's a badge of honor!","ja":"右眼の傷は、リーファどの絆なんだ潰れたままの右眼が、おでの勲章だ"},"kind":"dialogue"},{"uid":"talk.event_ch20_3_01#originalText","id":"talk.event_ch20_3_01","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"为什么你这么憎恨桐人？他有对你做什么吗？","en":"Why do you hate Kirito so much? What did he ever do to you?","ja":"どうしてそんなにキリトくんを憎むの彼が、あなたに何をしたの"},"kind":"dialogue"},{"uid":"talk.event_ch20_3_02#originalText","id":"talk.event_ch20_3_02","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"我还以为妳会了解我有多爱那家伙呢。","en":"I thought you, of all people, would understand how much I love that guy.","ja":"オレがどれほどあいつを愛しているかアンタならわかってくれると思ってたけどな"},"kind":"dialogue"},{"uid":"talk.event_ch20_3_03#originalText","id":"talk.event_ch20_3_03","speaker":{"cn":"索尔缇莉娜","en":"Sortiliena","ja":"ソルティリーナ"},"text":{"cn":"糟了……那男人的剑在吸收神圣力！！","en":"Oh, no... That man's sword is absorbing sacred resources!","ja":"いけない……あの男の剣が神聖力を吸収しています!!"},"kind":"dialogue"},{"uid":"talk.event_ch20_3_04#originalText","id":"talk.event_ch20_3_04","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"这个连接……是来自Underworld的物体……","en":"What's this connection? Is it coming from an object inside Underworld?","ja":"……なんだ?この接続は……アンダーワールド内のオブジェクトだ……"},"kind":"dialogue"},{"uid":"talk.event_ch20_3_05#originalText","id":"talk.event_ch20_3_05","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"这是……","en":"Where am I?","ja":"これは……"},"kind":"dialogue"},{"uid":"talk.event_ch21_1_01#originalText","id":"talk.event_ch21_1_01","speaker":{"cn":"瓦沙克","en":"Vassago","ja":"ヴァサゴ"},"text":{"cn":"来吧……让我尝尝你的血与生命吧，桐人！","en":"Come on... Let me taste your lifeblood, Kirito!","ja":"さあ……オマエの血と命を味わわせてくれキリト!"},"kind":"dialogue"},{"uid":"talk.event_ch21_1_02#originalText","id":"talk.event_ch21_1_02","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"桐人他不要紧的。他绝对……不会输给那种家伙。","en":"Kirito will be all right. He won't lose to that awful man. He'd never.","ja":"キリトくんは大丈夫あんな奴には負けない……絶対に"},"kind":"dialogue"},{"uid":"talk.event_ch21_1_03#originalText","id":"talk.event_ch21_1_03","speaker":{"cn":"缇洁","en":"Tiese","ja":"ティーゼ"},"text":{"cn":"拜托你，尤吉欧学长。救救桐人学长吧。","en":"Please. Eugeo... Save Kirito.","ja":"お願い、ユージオ先輩キリト先輩を、助けて"},"kind":"dialogue"},{"uid":"talk.event_ch21_1_04#originalText","id":"talk.event_ch21_1_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我不能再让你继续随心所欲，也不会让你这么做！","en":"I won't let you have your way any longer. I can't let you.","ja":"これ以上、お前の好きにはさせないさせるわけにはいかない"},"kind":"dialogue"},{"uid":"talk.event_ch21_1_05#originalText","id":"talk.event_ch21_1_05","speaker":{"cn":"凛子","en":"Rinko","ja":"凛子"},"text":{"cn":"界限加速是怎么回事！？FLA的倍率上限不是1200倍吗！？","en":"What does maximum acceleration mean?! Isn't the FLA rate limit 1,200?!","ja":"限界加速、ってどういうこと!?ＦＬＡの倍率は1200倍がリミットじゃなかったの!?"},"kind":"dialogue"},{"uid":"talk.event_story70_01#originalText","id":"talk.event_story70_01","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"升降盘的自动化……我的天职要消失了呢。不是的，我不是感到寂寞什么的……但是……","en":"Automating the floating platform means I won't have a calling anymore... I'm not sad but...","ja":"昇降盤の自動化……わたくしの天職はなくなるのですね。いえ、寂しいというわけではないのですが……"},"kind":"dialogue"},{"uid":"talk.event_story70_02#originalText","id":"talk.event_story70_02","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"虽然帮她取名字的事，交到了我的头上……但什么样的名字才会让她感到开心啊……","en":"She let me give her a name... But I wonder what kind of name would make her happy?","ja":"彼女に名前を付けてあげることになったんだけど……どんな名前なら喜んでくれるかな"},"kind":"dialogue"},{"uid":"talk.event_story70_03#originalText","id":"talk.event_story70_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"萨多雷先生真的是金属工艺师吗？居然连升降盘的自动化都可以做得到……","en":"Sadore, are you really just a goldsmith? The fact that you can automate the floating platform...","ja":"サードレさん、本当に金細工師なのかな。こんな、昇降盤の自動化までできちゃうなんて……"},"kind":"dialogue"},{"uid":"talk.event_story70_04#originalText","id":"talk.event_story70_04","speaker":{"cn":"升降员","en":"Operator","ja":"昇降係"},"text":{"cn":"我对这里以外的世界一无所知。我能够胜任其他的天职吗……应该会带给其他人困扰吧……","en":"Will I be able to do another calling besides this? I wouldn't want to cause anybody trouble...","ja":"この場所以外を知らないわたくしにほかの天職が務まるのでしょうかご迷惑をおかけしてしまうのでは……"},"kind":"dialogue"},{"uid":"talk.event_ch21_2_01#originalText","id":"talk.event_ch21_2_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"谢谢你……欢迎回来，桐人。","en":"Thank you. Welcome back, Kirito.","ja":"ありがとう……おかえりなさい、キリト"},"kind":"dialogue"},{"uid":"talk.event_ch21_2_02#originalText","id":"talk.event_ch21_2_02","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"相信桐人吧。我们得赶往世界尽头的祭坛。","en":"Let's believe in Kirito. We need to hurry to the World's End Altar.","ja":"キリトくんを信じましょうわたしたちは果ての祭壇に急がないと"},"kind":"dialogue"},{"uid":"talk.event_ch21_2_03#originalText","id":"talk.event_ch21_2_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"所以你一定要赢──获胜之后，再次回到我面前。","en":"You have to win. Win and come back to me again!","ja":"――絶対に勝って勝って、もういちど私の前に戻ってきて"},"kind":"dialogue"},{"uid":"talk.event_ch21_2_04#originalText","id":"talk.event_ch21_2_04","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"……你是什么人？","en":"Who are you?","ja":"……お前は、何者だ"},"kind":"dialogue"},{"uid":"talk.event_ch21_2_05#originalText","id":"talk.event_ch21_2_05","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"我本以为只要能拖延时间，直到她们注销就好了。如果能争取到时间──","en":"I thought I just had to prolong this battle long enough for Alice and Asuna to escape.","ja":"ふたりが脱出するまで戦いを引き延ばせればそれでいい時間さえ稼げれば――"},"kind":"dialogue"},{"uid":"talk.event_ch22_01#originalText","id":"talk.event_ch22_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"现实世界的各位，初次见面。我的名字是爱丽丝。爱丽丝‧辛赛西斯‧萨蒂。","en":"People of the real world, I'm pleased to meet you. I'm  Alice. Alice Synthesis Thirty.","ja":"リアルワールドの皆さんはじめまして私の名前はアリスアリス・シンセシス・サーティです"},"kind":"dialogue"},{"uid":"talk.event_ch22_02#originalText","id":"talk.event_ch22_02","speaker":{"cn":"珪子","en":"Keiko","ja":"珪子"},"text":{"cn":"那……那是我们学校的制服！！","en":"Ooh! That's our school uniform!","ja":"あっ……あれ、うちの制服!!"},"kind":"dialogue"},{"uid":"talk.event_ch22_03#originalText","id":"talk.event_ch22_03","speaker":{"cn":"诗乃","en":"Shino","ja":"詩乃"},"text":{"cn":"话说回来，这重现度太惊人了……隔着画面看几乎完全一样……","en":"Still, I'm amazed by the recreation they did. You can barely tell the difference through the screen.","ja":"それにしても、凄い再現度だわ……画面越しだと、ほとんど違いが……"},"kind":"dialogue"},{"uid":"talk.event_ch22_04#originalText","id":"talk.event_ch22_04","speaker":{"cn":"比嘉","en":"Higa","ja":"比嘉"},"text":{"cn":"怎么……怎么可能删除掉呢！！你是第一个撑过两百年时光的摇光！","en":"I couldn't...I couldn't delete you! You're the first fluctlight to survive the passage of 200 years!","ja":"消せる……消せるわけ、ないッスよ!!君は、200年という時間に耐え抜いた初のフラクトライトなんだ!"},"kind":"dialogue"},{"uid":"talk.event_ch22_05#originalText","id":"talk.event_ch22_05","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"桐人……我……好像要枯萎了一样……","en":"Kirito. I feel...I might wither away.","ja":"キリト……私、萎れてしまいそうです……"},"kind":"dialogue"},{"uid":"talk.event_story71_01#originalText","id":"talk.event_story71_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"我是从天界被召唤来的集成骑士、吗……？总觉得没什么实际的感觉耶。","en":"I am...an Integrity Knight, summoned by the heavens? It certainly doesn't feel that way...","ja":"あたしが天界から喚ばれた整合騎士、か……なんだか、全然実感わかないわね"},"kind":"dialogue"},{"uid":"talk.event_story71_02#originalText","id":"talk.event_story71_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"看到骑士长所持的那把剑后，身体动弹不得。我想这代表着骑士长究竟有多强大。","en":"Just looking at the Commander's sword makes my body freeze up. He's that strong.","ja":"騎士長が持っているあの剣を見ると体が固まっちゃうの。それだけ騎士長が強いってことかしら"},"kind":"dialogue"},{"uid":"talk.event_story71_03#originalText","id":"talk.event_story71_03","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"刚被招唤来的伊迪丝，感觉是个胆子很大的人。但似乎和法那提欧有些合不来就是了。","en":"That new recruit, Eydis, is quite the bold one, eh? I doubt she'd get along with someone like Fanatio.","ja":"新しく喚ばれたイーディスは、かなり肝が太そうだ。ファナティオとは少し合わなそうだがな"},"kind":"dialogue"},{"uid":"talk.event_story71_04#originalText","id":"talk.event_story71_04","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"如果把神器交给那孩子，会出现什么反应呢？稍微实验看看好了。","en":"I wonder what would happen if I gave them a divine weapon? Only one way to find out...","ja":"あの子に神器を持たせたらどうなるのかしら少し実験してみないと"},"kind":"dialogue"},{"uid":"talk.event_story72_01#originalText","id":"talk.event_story72_01","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这里就是雾舞的故乡啊。非常美丽的山和湖呢……不过这里一般人确实是很难靠近呢。","en":"This is Kirimai and the other Wyverns home. A lake in these beautiful mountains...Of course, this place is hard to reach for humans.","ja":"ここが、霧舞たち飛竜の故郷なのねとても綺麗な山に湖……でも確かに人間がここまでくるのは難しいわね"},"kind":"dialogue"},{"uid":"talk.event_story72_02#originalText","id":"talk.event_story72_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"这就是我的神器《暗斩剑》，冰冷且令人感到不可思议的触感……这把剑的记忆……必须好好驾御才行。","en":"Here is my divine weapon, the Dark Slash Sword. It's cold with an odd touch to it... I must master the memory of this sword.","ja":"これがあたしの神器《闇斬剣》冷たくて、不思議な手触り……この剣の記憶、きちんと制御しなきゃ"},"kind":"dialogue"},{"uid":"talk.event_story72_03#originalText","id":"talk.event_story72_03","speaker":{"cn":"卡迪娜尔","en":"Cardinal","ja":"カーディナル"},"text":{"cn":"我、正在寻找可以对抗集成骑士的人类。违反指数既高又剑术优良的人……","en":"I was looking for humans who could go up against the Integrity Knights. Humans who were highly skilled with a sword as well as the sacred arts and high index violations.","ja":"わしは、整合騎士に対抗できる人間を探していたのじゃ。違反指数が高く剣や術に優れた者を……"},"kind":"dialogue"},{"uid":"talk.event_story72_04#originalText","id":"talk.event_story72_04","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"关于合成的术式，仍有改良的空间。为了确认这件事，必须让伊迪丝加油试试看才行。","en":"There is room for improvement in the Synthesis Ritual. And to confirm that, I need Eydis to do her best.","ja":"シンセサイズの術式には、まだ改良の余地がある。それを確かめるためにもイーディスには頑張ってもらわないと"},"kind":"dialogue"},{"uid":"talk.event_story77_01#originalText","id":"talk.event_story77_01","speaker":{"cn":"涅鲁基乌斯","en":"Nergius","ja":"ネルギウス"},"text":{"cn":"我的实力果然还远远不及珀莉姊姊……","en":"I wish I were stronger. I still don't hold a candle to Paulie at all.","ja":"やはり、私の腕はまだまだポーリィ姉上には及ばぬ……"},"kind":"dialogue"},{"uid":"talk.event_story77_02#originalText","id":"talk.event_story77_02","speaker":{"cn":"珀莉","en":"Paulie","ja":"ポーリィ"},"text":{"cn":"你下意识地认定自己无法超越我这个师父。","en":"You have merely convinced yourself that you will never surpass me, your mentor.","ja":"あなたは師であるわたしを超えられない無意識にそう思い込んでいるのです"},"kind":"dialogue"},{"uid":"talk.event_story77_03#originalText","id":"talk.event_story77_03","speaker":{"cn":"恩特基尔","en":"Entokia","ja":"エントキア"},"text":{"cn":"……唔～今天不管怎么挖，都只挖到烂石头啊。","en":"Hmmm... No matter how deep we dig, there've been nothing but duds today.","ja":"……うーん、今日は掘っても掘っても出てくるのはクズ石ばっかりだなあ"},"kind":"dialogue"},{"uid":"talk.event_story77_04#originalText","id":"talk.event_story77_04","speaker":{"cn":"亚雷欧","en":"Aleo","ja":"アレオ"},"text":{"cn":"要是这一带能采掘到这么珍贵的矿石，我们的生活也能过得轻松一点吧？","en":"Well, if we could dig up a rare stone like this, we'd be livin' like kings, right?","ja":"ここいらで、もしこんな珍しい石が採れれば俺たちの暮らしも少しは楽になるだろ?"},"kind":"dialogue"},{"uid":"talk.event_story73_01#originalText","id":"talk.event_story73_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"奇怪、我是什么时候登录ALO的……完全想不起来啊。","en":"Wait, why am I logged into ALO?... I don't remember a thing.","ja":"あれ、俺はいつの間にALOにログインしたんだっけ……よく覚えていないなあ"},"kind":"dialogue"},{"uid":"talk.event_story73_02#originalText","id":"talk.event_story73_02","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"我才会是收集到全部礼服部件的人。不管是谁，只要是阻碍我的人我都不会轻易饶恕他的！","en":"The only one gathering up the dress pieces is me! And anybody who gets in my way will be sorry!","ja":"ドレスのパーツを全て集めるのはこのわたしよ。立ちはだかる者はたとえ誰であっても容赦はしない!"},"kind":"dialogue"},{"uid":"talk.event_story73_03#originalText","id":"talk.event_story73_03","speaker":{"cn":"尤金","en":"Eugene","ja":"ユージーン"},"text":{"cn":"想要礼服的左脚部件的话，就打倒我吧！","en":"If you want the left-sleeve of this dress, then you'll have to go through me!","ja":"ドレスの左脚衣装が欲しければこの俺を倒していくがいい！"},"kind":"dialogue"},{"uid":"talk.event_story73_04#originalText","id":"talk.event_story73_04","speaker":{"cn":"朔夜","en":"Sakuya","ja":"サクヤ"},"text":{"cn":"这次我和亚丽莎是共同战线！毕竟最大的敌人可是那个亚丝娜啊！","en":"Alicia is on my side this time! Any big fella won't stand a chance against Asuna!","ja":"今回はアリシャとの共同戦線だ最大の敵は、なんといってもあのアスナくんだからな"},"kind":"dialogue"},{"uid":"talk.event_story73_05#originalText","id":"talk.event_story73_05","speaker":{"cn":"亚丽莎","en":"Alicia","ja":"アリシャ"},"text":{"cn":"独占桐人禁止法！因为我也想要当桐人的新娘呀！","en":"We won't let you have Kirito all to yourself! Because Kirito's bride to be will be ME!","ja":"キリト君独占禁止法!アタシだって、キリト君の花嫁になりたいんだからネ!"},"kind":"dialogue"},{"uid":"talk.event_mc1_01#originalText","id":"talk.event_mc1_01","speaker":{"cn":"罗妮耶","en":"Ronie","ja":"ロニエ"},"text":{"cn":"……果然，变成这样了啊。不祥的预感成真了。","en":"I was afraid this would happen... What a bad omen.","ja":"……やっぱりこうなっちゃったんだなあ嫌な予感、当たっちゃった"},"kind":"dialogue"},{"uid":"talk.event_mc1_02#originalText","id":"talk.event_mc1_02","speaker":{"cn":"亚丝娜","en":"Asuna","ja":"アスナ"},"text":{"cn":"早安，罗妮耶小姐今天就像是祭典一样，可以放轻松一点没关系喔","en":"Good morning, Ronie. Since today is similar to a festival day, you can go ahead and relax a bit.","ja":"おはよう、ロニエさん今日はお祭りみたいなものだしもっと気楽にしてもいいのよ"},"kind":"dialogue"},{"uid":"talk.event_mc1_03#originalText","id":"talk.event_mc1_03","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"嗨，罗妮耶！你好吗？月驱！","en":"Heya, Ronie! How ya doin', Tsukigake?","ja":"おっす、ロニエ!元気か、月駆!"},"kind":"dialogue"},{"uid":"talk.event_mc1_04#originalText","id":"talk.event_mc1_04","speaker":{"cn":"萨多雷","en":"Sadore","ja":"サードレ"},"text":{"cn":"这个嘛，我也不知道搭乘的不是我，而是桐人小子啊","en":"I dunno. I'm not the one riding in it. The boy is. ","ja":"さて、わしゃ知らんよ乗るのはわしでなくキリ坊じゃもの"},"kind":"dialogue"},{"uid":"talk.event_mc1_05#originalText","id":"talk.event_mc1_05","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"抱歉，罗妮耶，可以麻烦妳帮忙照顾一下贝尔切吗？","en":"Would you mind watching Berche for a bit, Ronie?","ja":"ロニエ、悪いんだけどベルチェの面倒を見てくれないかしら"},"kind":"dialogue"},{"uid":"talk.event_story79_01#originalText","id":"talk.event_story79_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"就连施展治愈的术式雨缘的伤也无法治好。要是雨缘也有什么万一的话，我……","en":"No healing art seems to be having any effect on Amayori's wounds. If something were to happen...","ja":"なんど治癒の術式をかけても雨縁の傷は治らない。もし雨縁にまでなにかあったら、私は……"},"kind":"dialogue"},{"uid":"talk.event_story79_02#originalText","id":"talk.event_story79_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"在飞龙们的故乡，有飞龙们喜欢的药草的样子。当作触媒使用的话，雨缘的伤可能也会好的快点！","en":"There's a herb that wyverns like in their birthplace. It should help with the wounds if we use it.","ja":"飛竜たちの故郷には、飛竜たちが好む薬草があるんだって。触媒に使えば雨縁の傷もよくなるかも!"},"kind":"dialogue"},{"uid":"talk.event_story79_03#originalText","id":"talk.event_story79_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"飞龙们的故乡……是个非常美好的地方呢。总觉得好像来到其他世界了一样。","en":"The wyvern's birthplace is so beautiful... It's almost like we walked into another world.","ja":"飛竜たちの故郷……素敵な場所ですねなんだか別の世界に来てしまったようです"},"kind":"dialogue"},{"uid":"talk.event_story79_04#originalText","id":"talk.event_story79_04","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"雨缘也好，艾尔多利耶乘坐的泷刳也好，都因为母亲刚过世而感到悲伤呢……","en":"Amayori and Eldrie's Takiguri just lost their mother. I can't imagine their pain...","ja":"雨縁も、エルドリエが乗ってる滝刳もお母さんを亡くしたばかりで悲しいんだよね……"},"kind":"dialogue"},{"uid":"talk.event_story80_01#originalText","id":"talk.event_story80_01","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"雨缘能恢复健康真是太好了。必须和伊迪丝阁下以及告诉我们关于药草一事的阿优哈阁下道谢才行。","en":"Thank heavens Amayori is feeling better! I need to thank Eydis and Ayuha about the herb.","ja":"雨縁が元気になって本当によかったイーディス殿と、薬草のことを教えてくれたアユハ殿に礼を言わねば"},"kind":"dialogue"},{"uid":"talk.event_story80_02#originalText","id":"talk.event_story80_02","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"雨缘恢复健康，爱丽丝的脸色也变得好多了。接下来，就剩和爱丽丝两人快乐地享受剩余的时光而已了呢！","en":"Alice looks better now that Amayori is healthy again. So we can finally have our girls time!","ja":"雨縁が元気になって、アリスの顔色もよくなってきたわ。あとは、アリスとふたりで楽しい時間を過ごすだけね!"},"kind":"dialogue"},{"uid":"talk.event_story80_03#originalText","id":"talk.event_story80_03","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"雨缘和雾舞很介意森林中的样子。虽然好像不是敌人……但以防万一，还是去确认看看好了。","en":"Amayori and Kirimai senses something in the forest. Doesn't seem hostile...let's check it out!","ja":"雨縁と霧舞が森の中を気にしています敵ではないようですが……念のため、確認してみましょう"},"kind":"dialogue"},{"uid":"talk.event_story80_04#originalText","id":"talk.event_story80_04","speaker":{"cn":"艾尔多利耶","en":"Eldrie","ja":"エルドリエ"},"text":{"cn":"伊迪丝阁下到底要带走爱丽丝大人到何时啊！要是有骑士长和副长阁下的命令的话，就能立刻去迎接她了……","en":"How long does Eydis intend to drag Alice around?! If only I had orders from higher up, I would...","ja":"イーディス殿はいつまでアリス様を連れ回すつもりだ! 騎士長や副長殿の命があれば、お迎えに行けるのに……"},"kind":"dialogue"},{"uid":"talk.event_story80_05#originalText","id":"talk.event_story80_05","speaker":{"cn":"爱丽丝","en":"Alice","ja":"アリス"},"text":{"cn":"在户外脱下铠甲，我总觉得不太放心……","en":"Taking off my armor outside... how do I describe it? I feel exposed...","ja":"屋外で鎧を外すと、なんだか頼りない感じがします……"},"kind":"dialogue"},{"uid":"talk.event_story80_06#originalText","id":"talk.event_story80_06","speaker":{"cn":"伊迪丝","en":"Eydis","ja":"イーディス"},"text":{"cn":"好～那爱丽丝，我们来比赛看谁先游到对岸吧！","en":"Alright Alice! I'll race ya to that coast over there!","ja":"よーし、それじゃアリス向こうの岸まで競争しよう!"},"kind":"dialogue"},{"uid":"talk.event_story81_01#originalText","id":"talk.event_story81_01","speaker":{"cn":"法那提欧","en":"Fanatio","ja":"ファナティオ"},"text":{"cn":"该、该不会是！？黑暗界军队的袭击……吧？","en":"It...can't be?! Could it be an attack... from the Dark Territory?","ja":"ま、まさか!?暗黒界の軍勢の襲撃……でしょうか"},"kind":"dialogue"},{"uid":"talk.event_story81_02#originalText","id":"talk.event_story81_02","speaker":{"cn":"贝尔库利","en":"Bercouli","ja":"ベルクーリ"},"text":{"cn":"这个地方异常地炎热啊，就算是萨查库罗伊斯也已经入夜了啊。","en":"It's quite hot around here, even for Southacroith. And it's already dark.","ja":"この辺りはやけに暑いないくらサザークロイスでももう夜だぜ"},"kind":"dialogue"},{"uid":"talk.event_story81_03#originalText","id":"talk.event_story81_03","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"说说看你想要什么。这可是100年份的报酬哦。","en":"Tell me what it is you desire. It will be your reward for 100 years of servitude.","ja":"欲しいものを言ってご覧なさいなこれは100年分の報酬よ"},"kind":"dialogue"},{"uid":"talk.event_story81_04#originalText","id":"talk.event_story81_04","speaker":{"cn":"亚多米尼史特蕾达","en":"Administrator","ja":"アドミニストレータ"},"text":{"cn":"原本想说会要求些什么跳脱常理的东西……真是的，那个男的实在难以捉摸。","en":"To think he would request something more grand... That man really is unpredictable. ","ja":"さぞ大それたものを要求してくると思えば……まったく、あの男は本当に読めないわね"},"kind":"dialogue"},{"uid":"talk.event_story74_01#originalText","id":"talk.event_story74_01","speaker":{"cn":"桐人","en":"Kirito","ja":"キリト"},"text":{"cn":"其实我想拜托你们帮我做一个东西。","en":"There's something I'd like you both to build for me.","ja":"実はさ、老師とエアリーに造ってほしい物があるんだ"},"kind":"dialogue"},{"uid":"talk.event_story74_02#originalText","id":"talk.event_story74_02","speaker":{"cn":"萨多雷","en":"Sadore","ja":"サードレ"},"text":{"cn":"你说飞上天？还要和飞龙一样快，真是强人所难……","en":"You want to...fly? And as fast as a dragon, at that? You're out of your mind, boy.","ja":"空を飛ぶ、じゃと?しかも、飛竜ほどの速さとは無茶を言いよる……"},"kind":"dialogue"}]};
